<?php require 'config/db.php';require 'includes/auth.php';require_login();$page_title='Security Dashboard';$ci=$pdo->query("SELECT COUNT(*) FROM incidents WHERE status!='Resolved'")->fetchColumn();$ct=$pdo->query("SELECT COUNT(*) FROM threats WHERE status IN('Monitoring','Active')")->fetchColumn();$ca=$pdo->query("SELECT COUNT(*) FROM alerts WHERE status='Open'")->fetchColumn();$cm=$pdo->query("SELECT COUNT(*) FROM response_teams WHERE status!='Offline'")->fetchColumn();$recent=$pdo->query('SELECT incident_type,location,severity,status,date_reported FROM incidents ORDER BY id DESC LIMIT 8')->fetchAll();require 'includes/header.php';?><div class="cards"><div class="card">Open Incidents<strong><?=$ci?></strong></div><div class="card">Active Threats<strong><?=$ct?></strong></div><div class="card">Open Alerts<strong><?=$ca?></strong></div><div class="card">Available/Busy Teams<strong><?=$cm?></strong></div></div><section class="panel"><div class="sectionhead"><h2>Recent Incidents</h2><a class="btn" href="incidents.php">Manage Incidents</a></div><table><tr><th>Type</th><th>Location</th><th>Severity</th><th>Status</th><th>Date</th></tr><?php foreach($recent as $r):?><tr><td><?=e($r['incident_type'])?></td><td><?=e($r['location'])?></td><td><span class="badge <?=strtolower($r['severity'])?>"><?=e($r['severity'])?></span></td><td><?=e($r['status'])?></td><td><?=e($r['date_reported'])?></td></tr><?php endforeach;?></table></section><?php require 'includes/footer.php';?>
